import json
import datetime

class StructuredLogEvent:
    def __init__(self, message: str, severity: str, service: str, metadata: dict = None):
        self.message = message
        self.severity = severity
        self.service = service
        self.timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
        self.metadata = metadata if metadata is not None else {}

    def to_json(self):
        log_entry = {
            "timestamp": self.timestamp,
            "severity": self.severity,
            "service": self.service,
            "message": self.message,
            **self.metadata
        }
        return json.dumps(log_entry)

import boto3
import os

class ObservabilityClient:
    def __init__(self):
        self.client = boto3.client('logs', region_name=os.getenv('AWS_REGION', 'us-east-1'))
        self.log_group_name = os.getenv('AWS_LOG_GROUP_NAME', 'my-application-logs')

    def get_client(self):
        return self.client

    def get_log_group_name(self):
        return self.log_group_name

